import json
import re
import sys

def strict_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError('Duplicate JSON key: ' + key)
        result[key] = value
    return result
organization, definitionName = (sys.argv[9], sys.argv[10])
try:
    definitionVersion = int(sys.argv[3])
except Exception:
    definitionVersion = 0
descriptionValue = sys.argv[4]
descriptionProvided = bool(descriptionValue)
configProvided = bool(sys.argv[11])
tagsProvided = bool(sys.argv[12])
waitRequested = sys.argv[13] == 'true'
try:
    timeoutSeconds = int(sys.argv[8])
except Exception:
    timeoutSeconds = 0
errors, configs, parsedTags, catalogClauses = ([], [], [], [])
if not organization:
    errors.append('Workload Organization must not be blank.')
if not re.fullmatch('[A-Za-z0-9][A-Za-z0-9 _-]{0,31}', definitionName):
    errors.append('Workload Definition Name does not meet the public-schema pattern.')
if definitionVersion < 1:
    errors.append('Workload Definition Version must be at least 1.')
if len(descriptionValue) > 1024:
    errors.append('Description exceeds 1024 characters.')
if waitRequested and (not 30 <= timeoutSeconds <= 3600):
    errors.append('Wait Timeout Seconds must be from 30 through 3600.')
if configProvided:
    try:
        configs = json.loads(sys.argv[5], object_pairs_hook=strict_object)
    except Exception as exc:
        errors.append('Blueprint Configuration is invalid JSON: ' + str(exc))
        configs = []
    if not isinstance(configs, list) or not configs:
        errors.append('Blueprint Configuration replacement must be a non-empty array.')
if tagsProvided:
    try:
        parsedTags = json.loads(sys.argv[6], object_pairs_hook=strict_object)
    except Exception as exc:
        errors.append('Tags is invalid JSON: ' + str(exc))
        parsedTags = []
    if not isinstance(parsedTags, list):
        errors.append('Tags replacement must be an array.')
    elif any((not isinstance(tag, dict) or set(tag) - {'Key', 'Value'} or (not str(tag.get('Key') or '')) for tag in parsedTags)):
        errors.append('Every tag must contain a non-empty Key and optional Value only.')
if not (descriptionProvided or configProvided or tagsProvided):
    errors.append('At least one writable replacement must be supplied.')
normalized, localNames = ([], set())
if isinstance(configs, list):
    for index, item in enumerate(configs):
        if not isinstance(item, dict):
            errors.append('Blueprint Configuration entry %d must be an object.' % index)
            continue
        allowed = {'Name', 'CatalogSelectorType', 'CatalogName', 'CatalogMoid', 'BlueprintName', 'VersionSelection', 'Version', 'Input', 'InputOverride', 'ResourceConstraint'}
        if set(item) - allowed:
            errors.append('Blueprint Configuration entry %d contains unsupported fields.' % index)
        local = str(item.get('Name') or '').strip()
        selector = str(item.get('CatalogSelectorType') or '').strip()
        blueprint = str(item.get('BlueprintName') or '').strip()
        selection = str(item.get('VersionSelection') or '').strip()
        catalogName = str(item.get('CatalogName') or '').strip()
        catalogMoid = str(item.get('CatalogMoid') or '').strip()
        try:
            requestedVersion = int(item.get('Version', 0))
        except Exception:
            requestedVersion = 0
        if not re.fullmatch('[A-Za-z0-9][A-Za-z0-9 _-]{0,31}', local) or local in localNames:
            errors.append('Blueprint local Name at entry %d is invalid or duplicate.' % index)
        localNames.add(local)
        if selector not in ('Name', 'Moid') or (selector == 'Name' and (not catalogName)) or (selector == 'Moid' and (not re.fullmatch('[0-9A-Fa-f]{24}', catalogMoid))):
            errors.append('Catalog selector at entry %d is invalid.' % index)
        if not re.fullmatch('[A-Za-z0-9][A-Za-z0-9_]{0,31}', blueprint):
            errors.append('BlueprintName at entry %d is invalid.' % index)
        if selection not in ('Default', 'Specific') or (selection == 'Specific' and requestedVersion < 1):
            errors.append('Version selector at entry %d is invalid.' % index)
        inputValue = item.get('Input', {})
        overrides = item.get('InputOverride', [])
        constraint = item.get('ResourceConstraint')
        if not isinstance(inputValue, dict) or not isinstance(overrides, list) or any((not isinstance(v, str) for v in overrides)):
            errors.append('Input or InputOverride at entry %d has the wrong shape.' % index)
        if constraint is not None and (not isinstance(constraint, dict) or set(constraint) - {'Input'} or (not isinstance(constraint.get('Input', {}), dict))):
            errors.append('ResourceConstraint at entry %d has the wrong shape.' % index)
        normalized.append({'Name': local, 'CatalogSelectorType': selector, 'CatalogName': catalogName, 'CatalogMoid': catalogMoid, 'BlueprintName': blueprint, 'VersionSelection': selection, 'Version': requestedVersion, 'Input': inputValue if isinstance(inputValue, dict) else {}, 'InputOverride': overrides if isinstance(overrides, list) else [], 'ResourceConstraint': constraint})
        catalogClauses.append("Moid eq '%s'" % catalogMoid if selector == 'Moid' else "Name eq '%s'" % catalogName.replace("'", "''"))
status, statusCode = ('invalid', 400) if errors else ('ok', 200)
message = ' '.join(errors) if errors else 'Update request is valid.'
resultJson = json.dumps({'error': message}, separators=(',', ':')) if errors else '{}'
ready = True
organizationUrl = "/api/v1/organization/Organizations?$filter=Name eq '%s'&$select=Moid,Name" % organization.replace("'", "''")
configJson = json.dumps(normalized, separators=(',', ':'), ensure_ascii=False)
tagsJson = json.dumps(parsedTags if isinstance(parsedTags, list) else [], separators=(',', ':'), ensure_ascii=False)
catalogUrl = '/api/v1/workflow/Catalogs?$filter=' + (' or '.join(sorted(set(catalogClauses))) if catalogClauses else "Moid eq '000000000000000000000000'") + '&$select=Moid,Name,Organization'

import json
import re
import sys

# HTTP evidence is independent from strict organization identity inspection.
# The connector contract supplies an integral HTTP status and Boolean success.
try:
    httpStatus = int(sys.argv[4])
except (ValueError, TypeError):
    httpStatus = 0
requestSucceeded = sys.argv[5].strip().lower() == "true"
if not requestSucceeded or httpStatus != 200:
    statusCode = httpStatus if 300 <= httpStatus < 600 else 502
    lookupStatus = "api-failure"
    message = "Organization lookup API request failed"
    errorMessage = "The organization request failed or returned a non-200 response."
    organizationMoid, organizationJson, inspectionComplete = "", "{}", False
    safeCode, safeMessage = "", ""
    try:
        payload = json.loads(sys.argv[1])
        # Preserve the native String projection used by the old safe allowlists.
        def text(value):
            return value if isinstance(value, str) else json.dumps(value, separators=(",", ":"), ensure_ascii=False)
        code = text(payload["Code"]) if isinstance(payload, dict) and "Code" in payload else ""
        detail = text(payload["Message"]) if isinstance(payload, dict) and "Message" in payload else ""
        if re.fullmatch(r"[A-Za-z0-9_.:-]{1,128}", code):
            safeCode = code
        if re.fullmatch(r"[A-Za-z0-9 _.,:()/+\-]{1,500}", detail) and not re.search(r"authorization|password|secret|token|api.?key|bearer|https?://", detail, re.IGNORECASE):
            safeMessage = detail
    except Exception:
        pass
    if safeMessage:
        errorMessage = safeMessage
    resultJson = json.dumps({"status":"api-failure", "upstreamStatus":httpStatus, "Code":safeCode, "Message":safeMessage}, separators=(",", ":"))
else:
    import json
    import re
    import sys
    statusCode, lookupStatus, message = 502, "invalid-response", "Organization response is invalid"
    organizationMoid, organizationJson = "", "{}"
    inspectionComplete = False
    try:
        payload = json.loads(sys.argv[1])
        if not isinstance(payload, dict): raise ValueError("Organization response must be an object")
        count, rows = payload.get("Count"), payload.get("Results")
        if isinstance(count, bool) or not isinstance(count, int) or count < 0: raise ValueError("Count must be a nonnegative integer")
        if not isinstance(rows, list): raise ValueError("Results must be an array")
        if count != len(rows): raise ValueError("Count and Results length differ; the bounded page is incomplete")
        if count > 2: raise ValueError("Count exceeds the two-row lookup bound")
        if count == 0: statusCode, lookupStatus, message = 404, "not-found", "No organization matched the exact requested name"
        elif count != 1: statusCode, lookupStatus, message = 409, "ambiguous", "More than one organization matched the exact requested name"
        else:
            item = rows[0]
            if not isinstance(item, dict) or item.get("Name") != sys.argv[2]: raise ValueError("Organization Name does not match exactly")
            if item.get("ObjectType") != "organization.Organization" or item.get("ClassId") != "organization.Organization": raise ValueError("Organization discriminators do not match")
            moid = item.get("Moid")
            pattern = r"[0-9a-fA-F]{24}" if sys.argv[3] == "Hex24" else r"[A-Za-z0-9][A-Za-z0-9._~-]{0,127}"
            if not isinstance(moid, str) or re.fullmatch(pattern, moid) is None: raise ValueError("Organization Moid is missing or malformed")
            organizationMoid = moid
            projected = {key:item[key] for key in ("Moid", "Name", "ObjectType", "ClassId")}
            organizationJson = json.dumps(projected, separators=(",", ":"))
            resultJson = json.dumps({"Count":1,"Results":[projected]}, separators=(",", ":"))
            statusCode, lookupStatus, message = 200, "exact", "Organization resolved exactly"
        inspectionComplete = True
    except Exception as exc:
        statusCode, lookupStatus, message, inspectionComplete = 502, "invalid-response", str(exc), True
    errorMessage = "" if statusCode == 200 else message
    if statusCode != 200: resultJson = json.dumps({"status":lookupStatus,"error":message}, separators=(",", ":"))

import json
import sys

def has_default(definition):
    default = definition.get('Default')
    return isinstance(default, dict) and 'Value' in default

def validate_values(values, definitions, context):
    errors = []
    if not isinstance(values, dict):
        return [context + ' must be a JSON object.']
    definitions = definitions or []
    if not isinstance(definitions, list):
        return [context + ' definition is not an array.']
    for definition in definitions:
        if not isinstance(definition, dict):
            errors.append(context + ' contains a malformed data-type definition.')
            continue
        name = definition.get('Name')
        if not name:
            errors.append(context + ' contains an unnamed data-type definition.')
            continue
        if definition.get('Required') is True and name not in values and (not has_default(definition)):
            errors.append(context + ' is missing required value ' + name + '.')
            continue
        if name not in values:
            continue
        value = values[name]
        objectType = definition.get('ObjectType') or definition.get('ClassId')
        if objectType == 'workflow.PrimitiveDataType':
            properties = definition.get('Properties') or {}
            kind = properties.get('Type', 'string')
            valid = kind in ('string', 'enum') and isinstance(value, str) or (kind == 'integer' and isinstance(value, int) and (not isinstance(value, bool))) or (kind == 'float' and isinstance(value, (int, float)) and (not isinstance(value, bool))) or (kind == 'boolean' and isinstance(value, bool)) or (kind == 'json')
            if not valid:
                errors.append(context + '.' + name + ' does not match primitive type ' + kind + '.')
                continue
            constraints = properties.get('Constraints') or {}
            minimum, maximum = (constraints.get('Min'), constraints.get('Max'))
            measured = len(value) if isinstance(value, str) else value
            if minimum not in (None, 0) and measured < minimum:
                errors.append(context + '.' + name + ' is below its minimum constraint.')
            if maximum not in (None, 0) and measured > maximum:
                errors.append(context + '.' + name + ' exceeds its maximum constraint.')
            enumList = constraints.get('EnumList') or []
            if kind == 'enum' and enumList:
                allowed = [entry.get('Value') for entry in enumList if isinstance(entry, dict)]
                if value not in allowed:
                    errors.append(context + '.' + name + ' is not in the blueprint enum.')
        elif objectType == 'workflow.ArrayDataType':
            if not isinstance(value, list):
                errors.append(context + '.' + name + ' must be an array.')
            elif definition.get('Min') is not None and len(value) < int(definition['Min']):
                errors.append(context + '.' + name + ' has too few items.')
            elif definition.get('Max') is not None and len(value) > int(definition['Max']):
                errors.append(context + '.' + name + ' has too many items.')
        elif objectType in ('workflow.CustomDataType', 'workflow.DynamicTemplateParserDataType'):
            errors.append(context + '.' + name + ' uses a custom data type whose complete constraint schema is not present on the blueprint response; live-tenant validation is required and the workflow fails closed.')
        elif objectType and objectType.startswith('workflow.MoReference'):
            if not isinstance(value, dict):
                errors.append(context + '.' + name + ' must be a managed-object reference object.')
    return errors

def strip_reference(config, blueprint):
    reference = {'ClassId': 'workload.BlueprintReference', 'ObjectType': 'workload.BlueprintReference', 'Name': config['Name'], 'Blueprint': {'ClassId': 'mo.MoRef', 'ObjectType': 'workload.Blueprint', 'Moid': blueprint['Moid']}, 'Input': config.get('Input') or {}, 'InputOverride': config.get('InputOverride') or []}
    constraint = config.get('ResourceConstraint')
    if isinstance(constraint, dict):
        reference['ResourceConstraint'] = {'ClassId': 'workload.ResourceConstraint', 'ObjectType': 'workload.ResourceConstraint', 'Input': constraint.get('Input') or {}}
    return reference
body = json.loads(sys.argv[1])
configs = json.loads(sys.argv[2])
current = json.loads(sys.argv[3])
descriptionProvided = sys.argv[9] == 'true'
descriptionValue = sys.argv[5]
configProvided = sys.argv[10] == 'true'
tagsProvided = sys.argv[11] == 'true'
tags = json.loads(sys.argv[8])
status, statusCode, message, resultJson, ready = ('ok', 200, 'Patch request built', '{}', False)
requestJson = ''
try:
    rows = body.get('Results') if isinstance(body, dict) else None
    if not isinstance(rows, list):
        raise ValueError('Blueprint response has no Results array.')
    references = []
    errors = []
    if configProvided:
        if current.get('Status') != 'Inactive':
            errors.append('Blueprint replacement requires definition Status Inactive.')
        for config in configs:
            matches = []
            for row in rows:
                catalog = row.get('Catalog') if isinstance(row, dict) else None
                versionMatch = row.get('DefaultVersion') is True if config['VersionSelection'] == 'Default' else int(row.get('Version', 0)) == config['Version']
                if isinstance(catalog, dict) and catalog.get('Moid') == config['ResolvedCatalogMoid'] and (row.get('Name') == config['BlueprintName']) and versionMatch:
                    matches.append(row)
            if len(matches) != 1:
                errors.append('Blueprint selector %s resolved %d results.' % (config['Name'], len(matches)))
                continue
            blueprint = matches[0]
            validation = blueprint.get('ValidationInformation') or {}
            if validation.get('EngineState') != 'Updated' or validation.get('State') != 'Valid':
                errors.append('Blueprint %s is not Updated and Valid.' % config['Name'])
                continue
            errors += validate_values(config.get('Input') or {}, blueprint.get('InputDefinition') or [], 'Blueprint input ' + config['Name'])
            errors += validate_values((config.get('ResourceConstraint') or {}).get('Input', {}), (blueprint.get('ResourceDefinition') or {}).get('InputDefinition') or [], 'Resource constraint ' + config['Name'])
            references.append(strip_reference(config, blueprint))
    if errors:
        status, statusCode, message = ('invalid', 422, ' '.join(errors))
        resultJson = json.dumps({'error': message, 'liveTenantCaveat': 'Custom blueprint data types fail closed.'}, separators=(',', ':'))
    else:
        payload = {'ClassId': 'workload.WorkloadDefinition', 'ObjectType': 'workload.WorkloadDefinition'}
        if descriptionProvided:
            payload['Description'] = descriptionValue
        if configProvided:
            payload['Blueprints'] = references
        if tagsProvided:
            payload['Tags'] = tags
        requestJson = json.dumps(payload, separators=(',', ':'), ensure_ascii=False)
        resultJson = requestJson
    ready = True
except Exception as exc:
    status, statusCode, message, resultJson, ready = ('malformed', 502, str(exc), json.dumps({'error': str(exc)}, separators=(',', ':')), True)

import json
import sys

status, statusCode, message, resultJson, ready = "ok", 200, "Validation state inspected", "{}", False
pollState = "pending"
finalResultJson = "{}"
try:
    body = json.loads(sys.argv[1])
    expectedMoid, expectedName, expectedVersion = sys.argv[2], sys.argv[3], int(sys.argv[4])
    if not isinstance(body, dict) or body.get("Moid") != expectedMoid or body.get("Name") != expectedName or int(body.get("Version", 0)) != expectedVersion:
        status, statusCode, message = "identity-mismatch", 409, "Polled definition identity changed."
    else:
        validation = body.get("ValidationInformation") or {}
        engineState, state = validation.get("EngineState"), validation.get("State")
        if engineState == "Updated" and state == "Valid":
            pollState, message = "success", "Definition validation completed successfully."
        elif engineState == "UpdateFailed" or state == "Invalid":
            pollState, message = "failure", "Definition validation failed."
        elif engineState in ("NotUpdated", "Updating", "Updated") and state in ("NotValidated", "Valid"):
            pollState, message = "pending", "Definition validation remains in progress."
        else:
            status, statusCode, message = "unexpected-state", 502, "Definition returned an undocumented validation-state combination."
        finalResultJson = json.dumps(body, separators=(",", ":"), ensure_ascii=False)
        resultJson = finalResultJson if status == "ok" else json.dumps({"error": message, "definition": body}, separators=(",", ":"))
    ready = True
except Exception as exc:
    status, statusCode, message = "malformed", 502, str(exc)
    resultJson, ready = json.dumps({"error": message}, separators=(",", ":")), True
